    /// <inheritdoc/>
    protected override bool GetInternal(global::LionWeb.Core.M3.Feature? feature, out object? result)
    {
        if (base.GetInternal(feature, out result))
            return true;
        if (SysmlLanguage.Instance.Definition_directedUsage.EqualsIdentity(feature))
        {
            result = DirectedUsage;
            return true;
        }

        if (SysmlLanguage.Instance.Definition_isVariation.EqualsIdentity(feature))
